import { Audio } from 'expo-av';

const B64 = {
  dk_jump: '',
  dk_land: '',
  dk_death: '',
  dk_win: '',
  dk_score: '',
  dk_barrel: '',
  dk_intro: '',
};

const SOUNDS = {};

export async function preloadDKSounds() {
  await Promise.all(
    Object.entries(B64).map(async ([name, b64]) => {
      const { sound } = await Audio.Sound.createAsync(
        { uri: 'data:audio/wav;base64,' + b64 },
        { shouldPlay: false }
      );
      SOUNDS[name] = sound;
    })
  );
}

export async function playDKSound(name) {
  const s = SOUNDS[name];
  if (!s) return;
  try {
    await s.setPositionAsync(0);
    await s.playAsync();
  } catch (_) {}
}

export async function unloadDKSounds() {
  await Promise.all(Object.values(SOUNDS).map(s => s?.unloadAsync?.()));
  for (const k of Object.keys(SOUNDS)) delete SOUNDS[k];
}
